{"command": "cat > /workspace/create_patterns.py << 'PYEOF'
import json

def note(name, octave):
    notes = {'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5, 'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11}
    return notes[name] + (octave + 1) * 12

def create_pattern(pattern_num, data):
    pattern = []
    for row, ch, note_val, inst, vol, eff, eff_param in data:
        pattern.append({
            "name": "pattern_set_cell",
            "arguments": {
                "pattern": pattern_num,
                "row": row,
                "channel": ch,
                "note": note_val,
                "instrument": inst,
                "volume": vol,
                "effect": eff,
                "effect_param": eff_param
            }
        })
    return pattern

batch = []
for p in range(16):
    batch.append({"name": "pattern_set_length", "arguments": {"pattern": p, "rows": 64}})

# ===== PATTERN 0: Intro - slowly building =====
p0_data = []
arp_notes = [note('A',3), note('C',4), note('E',4), note('A',4)]
for r in range(0, 64, 4):
    for i, n in enumerate(arp_notes):
        p0_data.append((r+i, 0, n, 1, 40, 0, 0))
for r in range(0, 64, 16):
    p0_data.append((r, 2, note('A',2), 2, 50, 0, 0))
for r in [0, 16, 32, 48]:
    p0_data.append((r, 3, note('A',3), 5, 30, 0, 0))
    p0_data.append((r, 3, note('C',4), 5, 30, 0, 0))
    p0_data.append((r, 3, note('E',4), 5, 30, 0, 0))
for r in range(0, 64, 32):
    p0_data.append((r, 4, note('C',4), 6, 64, 0, 0))
for r in range(0, 64, 4):
    p0_data.append((r, 6, note('C',4), 8, 30, 0, 0))
batch.extend(create_pattern(0, p0_data))

# ===== PATTERN 1: Intro continued - add snare =====
p1_data = []
arp_notes = [note('F',3), note('A',3), note('C',4), note('F',4)]
for r in range(0, 64, 4):
    for i, n in enumerate(arp_notes):
        p1_data.append((r+i, 0, n, 1, 40, 0, 0))
for r in range(0, 64, 16):
    p1_data.append((r, 2, note('F',2), 2, 50, 0, 0))
for r in [0, 16, 32, 48]:
    p1_data.append((r, 3, note('F',3), 5, 30, 0, 0))
    p1_data.append((r, 3, note('A',3), 5, 30, 0, 0))
    p1_data.append((r, 3, note('C',4), 5, 30, 0, 0))
for r in range(0, 64, 32):
    p1_data.append((r, 4, note('C',4), 6, 64, 0, 0))
for r in range(16, 64, 32):
    p1_data.append((r, 5, note('C',4), 7, 64, 0, 0))
for r in range(0, 64, 4):
    p1_data.append((r, 6, note('C',4), 8, 30, 0, 0))
batch.extend(create_pattern(1, p1_data))

# ===== PATTERN 2: Intro - C major =====
p2_data = []
arp_notes = [note('C',3), note('E',3), note('G',3), note('C',4)]
for r in range(0, 64, 4):
    for i, n in enumerate(arp_notes):
        p2_data.append((r+i, 0, n, 1, 45, 0, 0))
for r in range(0, 64, 16):
    p2_data.append((r, 2, note('C',2), 2, 50, 0, 0))
for r in [0, 16, 32, 48]:
    p2_data.append((r, 3, note('C',3), 5, 30, 0, 0))
    p2_data.append((r, 3, note('E',3), 5, 30, 0, 0))
    p2_data.append((r, 3, note('G',3), 5, 30, 0, 0))
for r in range(0, 64, 32):
    p2_data.append((r, 4, note('C',4), 6, 64, 0, 0))
for r in range(16, 64, 32):
    p2_data.append((r, 5, note('C',4), 7, 64, 0, 0))
for r in range(0, 64, 4):
    p2_data.append((r, 6, note('C',4), 8, 35, 0, 0))
batch.extend(create_pattern(2, p2_data))

# ===== PATTERN 3: Intro - G major (dominant) =====
p3_data = []
arp_notes = [note('G',3), note('B',3), note('D',4), note('G',4)]
for r in range(0, 64, 4):
    for i, n in enumerate(arp_notes):
        p3_data.append((r+i, 0, n, 1, 50, 0, 0))
for r in range(0, 64, 16):
    p3_data.append((r, 2, note('G',2), 2, 50, 0, 0))
for r in [0, 16, 32, 48]:
    p3_data.append((r, 3, note('G',3), 5, 30, 0, 0))
    p3_data.append((r, 3, note('B',3), 5, 30, 0, 0))
    p3_data.append((r, 3, note('D',4), 5, 30, 0, 0))
for r in range(0, 64, 32):
    p3_data.append((r, 4, note('C',4), 6, 64, 0, 0))
for r in range(16, 64, 32):
    p3_data.append((r, 5, note('C',4), 7, 64, 0, 0))
for r in range(0, 64, 4):
    p3_data.append((r, 6, note('C',4), 8, 40, 0, 0))
for r in [8, 24, 40, 56]:
    p3_data.append((r, 1, note('D',4), 10, 35, 0, 0))
    p3_data.append((r+2, 1, note('B',3), 10, 35, 0, 0))
batch.extend(create_pattern(3, p3_data))

# ===== PATTERNS 4-11: MAIN SECTION =====
chords = [
    ("Am", [note('A',3), note('C',4), note('E',4)], note('A',2), [note('A',3), note('C',4), note('E',4)]),
    ("F",  [note('F',3), note('A',3), note('C',4)], note('F',2), [note('F',3), note('A',3), note('C',4)]),
    ("C",  [note('C',3), note('E',3), note('G',3)], note('C',2), [note('C',3), note('E',3), note('G',3)]),
    ("G",  [note('G',3), note('B',3), note('D',4)], note('G',2), [note('G',3), note('B',3), note('D',4)]),
]

melody_am = [(0, note('E',4)), (4, note('C',4)), (8, note('A',3)), (12, note('E',4)),
    (16, note('E',4)), (20, note('C',4)), (24, note('A',3)), (28, note('B',3)),
    (32, note('C',4)), (36, note('E',4)), (40, note('D',4)), (44, note('C',4)),
    (48, note('A',3)), (52, note('G',3)), (56, note('E',3)), (60, note('A',3))]
melody_f = [(0, note('A',4)), (4, note('F',4)), (8, note('C',4)), (12, note('A',4)),
    (16, note('G',4)), (20, note('E',4)), (24, note('F',4)), (28, note('D',4)),
    (32, note('C',4)), (36, note('A',3)), (40, note('F',4)), (44, note('E',4)),
    (48, note('D',4)), (52, note('C',4)), (56, note('A',3)), (60, note('F',3))]
melody_c = [(0, note('G',4)), (4, note('E',4)), (8, note('C',4)), (12, note('G',4)),
    (16, note('E',4)), (20, note('D',4)), (24, note('C',4)), (28, note('E',4)),
    (32, note('G',4)), (36, note('E',4)), (40, note('C',4)), (44, note('E',4)),
    (48, note('G',4)), (52, note('E',4)), (56, note('C',4)), (60, note('G',3))]
melody_g = [(0, note('D',4)), (4, note('B',3)), (8, note('G',3)), (12, note('D',4)),
    (16, note('B',3)), (20, note('G',3)), (24, note('F#',3)), (28, note('G',3)),
    (32, note('D',4)), (36, note('B',3)), (40, note('G',3)), (44, note('B',3)),
    (48, note('D',4)), (52, note('B',3)), (56, note('G',3)), (60, note('D',3))]
melodies = [melody_am, melody_f, melody_c, melody_g]

counter_am = [(2, note('C',5)), (10, note('A',4)), (18, note('G',4)), (26, note('E',4)), (34, note('C',5)), (42, note('A',4)), (50, note('G',4)), (58, note('E',4))]
counter_f  = [(2, note('A',4)), (10, note('F',4)), (18, note('D',4)), (26, note('C',4)), (34, note('A',4)), (42, note('F',4)), (50, note('D',4)), (58, note('C',4))]
counter_c  = [(2, note('E',5)), (10, note('C',5)), (18, note('A',4)), (26, note('G',4)), (34, note('E',5)), (42, note('C',5)), (50, note('A',4)), (58, note('G',4))]
counter_g  = [(2, note('D',5)), (10, note('B',4)), (18, note('G',4)), (26, note('D',4)), (34, note('D',5)), (42, note('B',4)), (50, note('G',4)), (58, note('D',4))]
counters = [counter_am, counter_f, counter_c, counter_g]

pluck_pattern = [(14, note('E',5)), (30, note('C',5)), (46, note('A',4)), (62, note('E',4))]

for chord_idx, (name, arp_notes, bass_note, pad_notes) in enumerate(chords):
    for pattern_repeat in range(2):
        p_num = 4 + chord_idx * 2 + pattern_repeat
        p_data = []
        for r in range(64):
            n = arp_notes[r % len(arp_notes)]
            p_data.append((r, 0, n, 1, 45 + pattern_repeat * 5, 0, 0))
        for r, n in melodies[chord_idx]:
            p_data.append((r, 1, n, 3 if pattern_repeat == 0 else 10, 50, 0, 0))
        for r, n in counters[chord_idx]:
            p_data.append((r, 7, n, 10, 35, 0, 0))
        for r in range(0, 64, 16):
            p_data.append((r, 2, bass_note, 11, 60, 0, 0))
            p_data.append((r+8, 2, bass_note + 12, 11, 50, 0, 0))
        for r in [0, 16, 32, 48]:
            for n in pad_notes:
                p_data.append((r, 3, n, 5, 25, 0, 0))
        for r in range(0, 64, 32):
            p_data.append((r, 4, note('C',4), 6, 64, 0, 0))
        for r in range(16, 64, 32):
            p_data.append((r, 5, note('C',4), 7, 64, 0, 0))
        for r in range(0, 64, 2):
            vol = 45 if r % 8 == 0 else 30
            inst = 8 if r % 4 == 0 else 9
            p_data.append((r, 6, note('C',4), inst, vol, 0, 0))
        if pattern_repeat == 1:
            for r, n in pluck_pattern:
                p_data.append((r, 3, n, 12, 40, 0, 0))
        batch.extend(create_pattern(p_num, p_data))

# ===== PATTERNS 12-15: BREAKDOWN / VARIATION =====
# Pattern 12: Breakdown
p12_data = []
for r in range(0, 64, 4):
    p12_data.append((r, 0, note('A',4), 4, 30, 0, 0))
for r in range(0, 64, 16):
    p12_data.append((r, 2, note('A',2), 2, 50, 0, 0))
for r in [0, 32]:
    for n in [note('A',3), note('C',4), note('E',4)]:
        p12_data.append((r, 3, n, 5, 20, 0, 0))
for r in range(0, 64, 32):
    p12_data.append((r, 4, note('C',4), 6, 64, 0, 0))
for r in range(0, 64, 8):
    p12_data.append((r, 6, note('C',4), 8, 25, 0, 0))
batch.extend(create_pattern(12, p12_data))

# Pattern 13: Build up
p13_data = []
arp = [note('A',3), note('C',4), note('E',4), note('A',4)]
for r in range(0, 64, 4):
    for i, n in enumerate(arp):
        p13_data.append((r+i, 0, n, 1, 40, 0, 0))
for r in range(0, 64, 16):
    p13_data.append((r, 2, note('F',2), 11, 55, 0, 0))
for r in [0, 16, 32, 48]:
    for n in [note('F',3), note('A',3), note('C',4)]:
        p13_data.append((r, 3, n, 5, 25, 0, 0))
for r in range(0, 64, 32):
    p13_data.append((r, 4, note('C',4), 6, 64, 0, 0))
for r in range(16, 64, 32):
    p13_data.append((r, 5, note('C',4), 7, 64, 0, 0))
